import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css';

function App() {
  const [atividades, setAtividades] = useState([]);
  const [paginaAtual, setPaginaAtual] = useState(1);
  const [usuario, setUsuario] = useState(null);
  
  // Estados para nova atividade
  const [tipo, setTipo] = useState('');
  const [distancia, setDistancia] = useState('');
  const [duracao, setDuracao] = useState('');
  const [calorias, setCalorias] = useState('');

  // Estados para Modal de Comentários
  const [atividadeComentarios, setAtividadeComentarios] = useState(null);
  const [listaComentarios, setListaComentarios] = useState([]);
  const [novoComentario, setNovoComentario] = useState('');

  // Modal Login
  const [mostrarModalAuth, setMostrarModalAuth] = useState(false);
  const [isCadastro, setIsCadastro] = useState(false);
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState('');

  const ITENS_POR_PAGINA = 2;

  useEffect(() => {
    carregarAtividades();
  }, [usuario]);

  const carregarAtividades = async () => {
    try {
      const url = usuario 
        ? `http://localhost:3000/atividades?usuarioId=${usuario.id}`
        : 'http://localhost:3000/atividades';
      const res = await axios.get(url);
      setAtividades(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleAuth = async (e) => {
    e.preventDefault();
    setErro('');
    const endpoint = isCadastro ? '/registrar' : '/login';
    try {
      const res = await axios.post(`http://localhost:3000${endpoint}`, { email, senha });
      setUsuario(res.data);
      setMostrarModalAuth(false);
      setEmail('');
      setSenha('');
    } catch (err) {
      setErro(err.response?.data?.error || 'Erro na requisição.');
    }
  };

  const handleCriarAtividade = async (e) => {
    e.preventDefault();
    if (!usuario) {
      setMostrarModalAuth(true);
      return;
    }
    try {
      await axios.post('http://localhost:3000/atividades', {
        tipo,
        distancia_m: distancia,
        duracao_min: duracao,
        calorias,
        usuarioId: usuario.id
      });
      setTipo('');
      setDistancia('');
      setDuracao('');
      setCalorias('');
      carregarAtividades();
    } catch (err) {
      alert('Erro ao criar atividade.');
    }
  };

  const handleCurtir = async (id) => {
    if (!usuario) {
      setMostrarModalAuth(true);
      return;
    }
    try {
      await axios.post(`http://localhost:3000/atividades/${id}/curtir`, {
        usuarioId: usuario.id
      });
      carregarAtividades();
    } catch (err) {
      alert(err.response?.data?.error || 'Erro ao curtir.');
    }
  };

  const abrirComentarios = async (atividade) => {
    setAtividadeComentarios(atividade);
    try {
      const res = await axios.get(`http://localhost:3000/atividades/${atividade.id}/comentarios`);
      setListaComentarios(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleEnviarComentario = async (e) => {
    e.preventDefault();
    if (!usuario) {
      setMostrarModalAuth(true);
      return;
    }
    try {
      await axios.post(`http://localhost:3000/atividades/${atividadeComentarios.id}/comentarios`, {
        texto: novoComentario,
        usuarioId: usuario.id
      });
      setNovoComentario('');
      abrirComentarios(atividadeComentarios);
      carregarAtividades();
    } catch (err) {
      alert('Erro ao enviar comentário.');
    }
  };

  const indiceUltimo = paginaAtual * ITENS_POR_PAGINA;
  const atividadesPaginadas = atividades.slice(indiceUltimo - ITENS_POR_PAGINA, indiceUltimo);
  const totalPaginas = Math.ceil(atividades.length / ITENS_POR_PAGINA);

  return (
    <div className="layout-saep">
      {/* Sidebar Esquerda */}
      <aside className="sidebar">
        <div className="sidebar-header">
          <div className="sidebar-logo">👤</div>
          <h2 className="sidebar-title">{usuario ? usuario.email.split('@')[0] : 'Usuário_03'}</h2>
        </div>
        <div className="sidebar-stats">
          <div>
            <span className="stat-value">{atividades.length}</span>
            <span className="stat-label">Qtd. Atividades</span>
          </div>
          <div>
            <span className="stat-value">50</span>
            <span className="stat-label">Qtd. Calorias</span>
          </div>
        </div>
        <div className="sidebar-menu">
          <a href="#atividade" className="menu-item active">
            📊 Atividade
          </a>
        </div>
        <div className="sidebar-footer">
          <strong>SAEPSaúde</strong>
          <p style={{ marginTop: '5px' }}>Copyright - 2025/2026</p>
        </div>
      </aside>

      {/* Conteúdo Principal */}
      <main className="main-content">
        <header className="content-header">
          {usuario ? (
            <button className="btn btn-dark" onClick={() => setUsuario(null)}>Logout</button>
          ) : (
            <button className="btn btn-dark" onClick={() => setMostrarModalAuth(true)}>Login</button>
          )}
        </header>

        {/* Categorias */}
        <div className="filter-bar">
          <button className="filter-item">Corrida</button>
          <button className="filter-item">Caminhada</button>
          <button className="filter-item">Trilha</button>
        </div>

        {/* Formulário: Crie sua atividade */}
        <section className="form-card">
          <h2 className="form-title">Crie sua atividade</h2>
          <form onSubmit={handleCriarAtividade}>
            <div className="form-grid">
              <div>
                <label>Tipo da atividade</label>
                <input className="input" placeholder="Ex: Caminhada" value={tipo} onChange={e => setTipo(e.target.value)} required />
              </div>
              <div>
                <label>Distância percorrida</label>
                <input className="input" placeholder="Ex: 1000 metros" value={distancia} onChange={e => setDistancia(e.target.value)} required />
              </div>
              <div>
                <label>Duração da atividade</label>
                <input className="input" placeholder="Ex: 120 min" value={duracao} onChange={e => setDuracao(e.target.value)} required />
              </div>
              <div>
                <label>Quantidade de Calorias</label>
                <input className="input" placeholder="Ex: 300" value={calorias} onChange={e => setCalorias(e.target.value)} required />
              </div>
            </div>
            <div className="form-actions">
              <button className="btn btn-dark" type="submit">Criar Atividade</button>
            </div>
          </form>
        </section>

        {/* Lista de Atividades */}
        <section className="feed-section">
          <h2 className="feed-title">Suas Atividades</h2>
          <div className="atividades-feed">
            {atividadesPaginadas.map((item) => (
              <div key={item.id} className="atividade-card">
                <div className="card-left">
                  <div className="avatar-placeholder">👤</div>
                  <span className="user-name">{item.Usuario ? item.Usuario.email.split('@')[0] : 'Usuário_03'}</span>
                </div>
                
                <div className="card-center">
                  <span className="atividade-tipo">{item.tipo}</span>
                  <div className="atividade-meta-data">
                    <span>{(item.distancia_m / 1000).toFixed(0)} km</span>
                    <span className="meta-label">Distância</span>
                  </div>
                  <div className="atividade-meta-data">
                    <span>{item.duracao_min} min</span>
                    <span className="meta-label">Duração</span>
                  </div>
                  <div className="atividade-meta-data">
                    <span>{item.calorias || 350}</span>
                    <span className="meta-label">Calorias</span>
                  </div>
                </div>

                <div className="card-right">
                  <span className="atividade-data">05:30 - 09/07/2024</span>
                  <div className="card-actions">
                    <span 
                      className={`action-item ${item.curtidoPeloUsuario ? 'curtido' : ''}`} 
                      onClick={() => handleCurtir(item.id)}
                    >
                      {item.curtidoPeloUsuario ? '❤️' : '♡'} {item.curtidas_count}
                    </span>
                    <span className="action-item" onClick={() => abrirComentarios(item)}>
                      💬 {item.comentarios_count}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Paginação */}
        {totalPaginas > 1 && (
          <div className="pagination">
            <button className="page-btn" disabled={paginaAtual === 1} onClick={() => setPaginaAtual(p => p - 1)}>Anterior</button>
            <button className={`page-number ${paginaAtual === 1 ? 'active' : ''}`} onClick={() => setPaginaAtual(1)}>1</button>
            {totalPaginas >= 2 && <button className={`page-number ${paginaAtual === 2 ? 'active' : ''}`} onClick={() => setPaginaAtual(2)}>2</button>}
            <button className="page-btn" disabled={paginaAtual === totalPaginas} onClick={() => setPaginaAtual(p => p + 1)}>Próximo</button>
          </div>
        )}
      </main>

      {/* Modal Login */}
      {mostrarModalAuth && (
        <div className="modal-overlay">
          <div className="modal">
            <h2>{isCadastro ? 'Criar Conta' : 'Acessar Conta'}</h2>
            {erro && <p className="error-msg">{erro}</p>}
            <form onSubmit={handleAuth}>
              <input className="input" type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} required />
              <input className="input" type="password" placeholder="Senha" value={senha} onChange={e => setSenha(e.target.value)} required />
              <button className="btn btn-dark" type="submit" style={{ width: '100%', marginBottom: '10px' }}>
                {isCadastro ? 'Cadastrar' : 'Entrar'}
              </button>
            </form>
            <button className="btn btn-secondary" style={{ width: '100%' }} onClick={() => { setIsCadastro(!isCadastro); setErro(''); }}>
              {isCadastro ? 'Já tenho conta' : 'Criar nova conta'}
            </button>
          </div>
        </div>
      )}

      {/* Modal de Comentários */}
      {atividadeComentarios && (
        <div className="modal-overlay">
          <div className="modal" style={{ width: '400px' }}>
            <h2>Comentários - {atividadeComentarios.tipo}</h2>
            <div className="comentarios-lista">
              {listaComentarios.length === 0 ? (
                <p style={{ fontSize: '0.85rem', color: '#666', marginBottom: '10px' }}>Nenhum comentário ainda.</p>
              ) : (
                listaComentarios.map(c => (
                  <div key={c.id} className="comentario-item">
                    <strong>{c.Usuario ? c.Usuario.email.split('@')[0] : 'Anônimo'}:</strong> {c.texto}
                  </div>
                ))
              )}
            </div>
            <form onSubmit={handleEnviarComentario}>
              <input 
                className="input" 
                placeholder="Escreva um comentário..." 
                value={novoComentario} 
                onChange={e => setNovoComentario(e.target.value)} 
                required 
              />
              <button className="btn btn-dark" type="submit" style={{ width: '100%', marginBottom: '8px' }}>Enviar Comentário</button>
            </form>
            <button className="btn btn-secondary" style={{ width: '100%' }} onClick={() => setAtividadeComentarios(null)}>Fechar</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
